hold_ticks := 0
if ((#Kitchen_Charger).charger_power < 5) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 1800) {
(#Kitchen_Charger).switch_off()
        break
}
}
else {
hold_ticks = 0
}

